(() => {
  try {
    const text = document.body.innerText;
    const stats = {};

    // Money - find number after yuan symbol or 元
    const moneyIdx = text.indexOf('元');
    if (moneyIdx > 0) {
      const before = text.substring(Math.max(0, moneyIdx - 15), moneyIdx);
      const m = before.match(/([\d,]+)/);
      if (m) stats.money = m[1].replace(/,/g, '');
    }

    // Stamina
    const staminaIdx = text.indexOf('⚡');
    if (staminaIdx >= 0) {
      const after = text.substring(staminaIdx, staminaIdx + 20);
      const m = after.match(/(\d+)\s*\/\s*(\d+)/);
      if (m) stats.stamina = m[1] + '/' + m[2];
    }

    // Health
    const healthIdx = text.indexOf('❤️');
    if (healthIdx >= 0) {
      const after = text.substring(healthIdx, healthIdx + 20);
      const m = after.match(/(\d+)\s*\/\s*(\d+)/);
      if (m) stats.health = m[1] + '/' + m[2];
    }

    // Season and day
    const seasonMatch = text.match(/(春季|夏季|秋季|冬季)\s*第\s*(\d+)\s*天/);
    if (seasonMatch) {
      stats.season = seasonMatch[1];
      stats.seasonDay = seasonMatch[2];
    }

    // Total days from event log
    const dayMatches = text.match(/\[第(\d+)天\]/g);
    if (dayMatches) {
      const days = dayMatches.map(m => parseInt(m.match(/\d+/)[0]));
      stats.maxEventDay = Math.max(...days);
    }

    // Fields count
    const fieldMatches = text.match(/第(\d+)块田/g);
    if (fieldMatches) {
      const nums = fieldMatches.map(m => parseInt(m.match(/\d+/)[0]));
      stats.fields = Math.max(...nums);
    }

    // Event count
    stats.eventCount = (text.match(/\[第\d+天\]/g) || []).length;

    // NPC好感度提取
    const npcFavor = {};
    const npcMatches = text.matchAll(/([^\s\[\]\n]{2,4})好感\+?(-?\d+)/g);
    for (const m of npcMatches) {
      const name = m[1];
      const val = parseInt(m[2]);
      npcFavor[name] = (npcFavor[name] || 0) + val;
    }
    stats.npcFavor = npcFavor;

    // 技能相关
    const skillMatches = text.matchAll(/([^\s\[\]\n]{2,6})经验\s*\+?(-?\d+)/g);
    const skills = {};
    for (const m of skillMatches) {
      const name = m[1];
      const val = parseInt(m[2]);
      skills[name] = (skills[name] || 0) + val;
    }
    stats.skills = skills;

    // 任务数量
    const taskMatch = text.match(/(\d+)\s*个待完成/);
    if (taskMatch) stats.pendingTasks = taskMatch[1];

    // 成就
    const achieveMatch = text.match(/已达成\s*(\d+)\s*\/\s*(\d+)/);
    if (achieveMatch) {
      stats.achievements = achieveMatch[1] + '/' + achieveMatch[2];
    }

    // 天气
    const weatherMatch = text.match(/(晴天|多云|阴天|小雨|中雨|大雨|暴雨|雷阵雨|雪|雾)/);
    if (weatherMatch) stats.weather = weatherMatch[1];

    return JSON.stringify(stats);
  } catch(e) {
    return JSON.stringify({error: e.message});
  }
})()
